impl<T:RetainedEquality> Drop for RetainedEqualityOwner<T>{fn drop(&mut self){if std::thread::panicking(){return}let empty=self.advance_route.is_none()&&self.close_route.is_none()&&self.cursor.is_none()&&self.left.is_none()&&self.right.is_none();assert!(empty,"original typed equality retains source/frontier custody");if empty{unsafe{std::mem::ManuallyDrop::drop(&mut self.cursor);std::mem::ManuallyDrop::drop(&mut self.left);std::mem::ManuallyDrop::drop(&mut self.right)}}}}

